function solve(s) {
  const size = s.length;
  let total = 0;
  for (let i = 0; i < size; i++) {
    let zeros = 0;
    let ones = 0;
    let runs = 1;
    let current = s[i];
    for (let j = i; j < size; j++) {
      if (s[j] !== current) {
        runs++;
        if (runs > 2) break;
        current = s[j];
      }
      if (s[j] === '0') zeros++; else ones++;
      if (zeros === ones) total++;
    }
  }
  return total;
}

function solve(s) {
  let total = 0;
  let previousRun = 0;
  let i = 0;
  const size = s.length;
  while (i < size) {
    let j = i;
    while (j < size && s[j] === s[i]) j++;
    const run = j - i;
    total += Math.min(previousRun, run);
    previousRun = run;
    i = j;
  }
  return total;
}
